function drawGround(){
 ctx.fillStyle='#82cf59';ctx.fillRect(0,0,W,H);
 // softly mottled grass and sandy arena paths
 for(let y=16;y<H;y+=38)for(let x=14;x<W;x+=42){let k=Math.sin(x*12.98+y*7.23)*43758.5;k=k-Math.floor(k);ctx.globalAlpha=.08+k*.06;ctx.fillStyle=k>.52?'#d7f184':'#397d47';ctx.beginPath();ctx.ellipse(x+(k-.5)*17,y+(k-.5)*13,randDet(x,y,7,14),3+k*3,k*3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 ctx.fillStyle='#d5b86b';ctx.beginPath();ctx.roundRect(25,26,950,648,32);ctx.fill();ctx.fillStyle='#91d25d';ctx.beginPath();ctx.roundRect(37,38,926,624,25);ctx.fill();
 // subtle boundary line
 ctx.strokeStyle='#e5cc7e';ctx.lineWidth=7;ctx.beginPath();ctx.roundRect(28,29,944,642,30);ctx.stroke();
 // arena speckles
 for(let i=0;i<95;i++){let x=44+randDet(i,2,12,910),y=45+randDet(i,3,10,610);ctx.fillStyle=i%2?'#ffffff12':'#477d3525';ctx.beginPath();ctx.arc(x,y,randDet(i,4,1,3),0,Math.PI*2);ctx.fill()}
 // center gem platform
 ctx.fillStyle='#588d48';ctx.beginPath();ctx.ellipse(500,350,77,69,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a3d66a';ctx.beginPath();ctx.ellipse(500,346,75,67,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#86c55b';ctx.beginPath();ctx.ellipse(500,346,59,52,0,0,Math.PI*2);ctx.fill();
 // path dashes
 ctx.strokeStyle='#e5d19466';ctx.lineWidth=4;ctx.setLineDash([8,14]);ctx.beginPath();ctx.moveTo(500,104);ctx.lineTo(500,255);ctx.moveTo(500,444);ctx.lineTo(500,596);ctx.moveTo(86,350);ctx.lineTo(420,350);ctx.moveTo(580,350);ctx.lineTo(914,350);ctx.stroke();ctx.setLineDash([]);
}
function randDet(n,k,a,b){let v=Math.sin(n*127.1+k*311.7)*43758.5453;v-=Math.floor(v);return a+v*(b-a)}
function drawWalls(){
 for(const w of walls){ctx.fillStyle='#4b6950';ctx.beginPath();ctx.roundRect(w.x,w.y+7,w.w,w.h,8);ctx.fill();ctx.fillStyle='#bd8950';ctx.beginPath();ctx.roundRect(w.x,w.y,w.w,w.h,8);ctx.fill();ctx.fillStyle='#d7a761';ctx.beginPath();ctx.roundRect(w.x+3,w.y+2,w.w-6,w.h-9,6);ctx.fill();ctx.fillStyle='#9c683f';ctx.fillRect(w.x+7,w.y+14,w.w-14,4);ctx.fillStyle='#edc179';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(w.x+13+i*(w.w-26)/2,w.y+7,2,0,Math.PI*2);ctx.fill()}}
}
function drawBushes(){for(const b of bushes){ctx.fillStyle='#4a9a48';ctx.beginPath();ctx.ellipse(b.x,b.y+b.h*.55,b.w*.54,b.h*.46,0,0,Math.PI*2);ctx.fill();for(let i=0;i<11;i++){let a=i*2.399,rr=.35+randDet(b.x+i,b.y,0,.24),x=b.x+Math.cos(a)*b.w*rr,y=b.y+Math.sin(a)*b.h*rr;ctx.fillStyle=i%3?'#57b94c':'#70ca55';ctx.beginPath();ctx.ellipse(x,y,b.w*.2,b.h*.22,randDet(i,b.x,0,3),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#367b3c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,b.w*.15,3.8,5.5);ctx.stroke()}}}
function drawGem(g){const bob=Math.sin(g.bob)*3;ctx.save();ctx.translate(g.x,g.y+bob);ctx.shadowColor='#16ffe1';ctx.shadowBlur=15;ctx.fillStyle='#21f4d0';ctx.strokeStyle='#c9fff5';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(10,-5);ctx.lineTo(8,7);ctx.lineTo(0,12);ctx.lineTo(-8,7);ctx.lineTo(-10,-5);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#ffffffaa';ctx.beginPath();ctx.moveTo(-2,-8);ctx.lineTo(3,-5);ctx.lineTo(0,0);ctx.closePath();ctx.fill();ctx.restore()}
function drawBrawler(o,isPlayer=false){
 ctx.save();ctx.translate(o.x,o.y);
 // ground shadow
 ctx.fillStyle='#1b3d3c45';ctx.beginPath();ctx.ellipse(1,16,24,10,0,0,Math.PI*2);ctx.fill();
 if(isPlayer&&o.invuln>0&&Math.floor(elapsed*14)%2===0)ctx.globalAlpha=.5;
 // feet
 ctx.fillStyle='#563d42';ctx.beginPath();ctx.ellipse(-10,14,7,5,-.2,0,Math.PI*2);ctx.ellipse(10,14,7,5,.2,0,Math.PI*2);ctx.fill();
 // body
 ctx.fillStyle=isPlayer?'#ef7049':o.color;ctx.beginPath();ctx.ellipse(0,3,17,19,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffff88';ctx.lineWidth=2;ctx.stroke();
 // bandana/scarf
 ctx.fillStyle=isPlayer?'#36b8ec':'#282e53';ctx.beginPath();ctx.ellipse(0,-4,17,7,0,0,Math.PI*2);ctx.fill();
 // face
 ctx.fillStyle='#ffd2a1';ctx.beginPath();ctx.ellipse(0,-5,12,12,0,0,Math.PI*2);ctx.fill();
 // ears
 ctx.beginPath();ctx.arc(-12,-5,4,0,Math.PI*2);ctx.arc(12,-5,4,0,Math.PI*2);ctx.fill();
 // hat
 ctx.fillStyle=isPlayer?'#ffe05a':'#dce8f8';ctx.beginPath();ctx.ellipse(0,-15,18,6,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.roundRect(-12,-27,24,13,5);ctx.fill();ctx.fillStyle=isPlayer?'#cf593a':'#58678a';ctx.fillRect(-12,-19,24,4);ctx.fillStyle='#fff4c4';ctx.beginPath();ctx.arc(0,-24,2.4,0,Math.PI*2);ctx.fill();
 // eyes
 ctx.fillStyle='#27364a';ctx.beginPath();ctx.arc(-4,-6,1.5,0,Math.PI*2);ctx.arc(4,-6,1.5,0,Math.PI*2);ctx.fill();
 // gun points toward aim
 let a=Math.atan2(o.aimY,o.aimX);ctx.save();ctx.rotate(a);ctx.fillStyle='#3b4658';ctx.beginPath();ctx.roundRect(8,-1,18,8,3);ctx.fill();ctx.fillStyle='#a8b7c8';ctx.fillRect(21,0,7,3);ctx.restore();
 if(!isPlayer){ctx.fillStyle='#14263b';ctx.font='900 9px DM Sans';ctx.textAlign='center';ctx.fillText(o.name,0,-37);}
 if(o.hp<o.maxHp){ctx.fillStyle='#24364b';ctx.beginPath();ctx.roundRect(-20,-33,40,5,3);ctx.fill();ctx.fillStyle='#70ef79';ctx.beginPath();ctx.roundRect(-19,-32,38*clamp(o.hp/o.maxHp,0,1),3,2);ctx.fill();}
 if(isPlayer&&o.gems>0){for(let i=0;i<Math.min(o.gems,5);i++){ctx.fillStyle='#20f5d0';ctx.beginPath();ctx.arc(-12+i*6,-34,3,0,Math.PI*2);ctx.fill()}}
 ctx.restore();
}
function drawShots(){for(const s of shots){ctx.save();ctx.shadowBlur=14;ctx.shadowColor=s.color;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore()}}

