function drawShots(){for(const s of shots){ctx.save();ctx.shadowBlur=14;ctx.shadowColor=s.color;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore()}}
function blocked(x,y,r){if(x<50+r||x>950-r||y<50+r||y>650-r)return true;return walls.some(w=>x+r>w.x&&x-r<w.x+w.w&&y+r>w.y&&y-r<w.y+w.h)}
function move(o,dx,dy){let nx=o.x+dx,ny=o.y+dy;if(!blocked(nx,o.y,o.r))o.x=nx;if(!blocked(o.x,ny,o.r))o.y=ny}
function fire(owner,target,bot=false,superShot=false){
 const dx=target.x-owner.x,dy=target.y-owner.y,base=Math.atan2(dy,dx),spread=bot?0.035:.105;
 if(bot){const a=base+rand(-spread,spread);shots.push({x:owner.x+Math.cos(a)*25,y:owner.y+Math.sin(a)*25,vx:Math.cos(a)*340,vy:Math.sin(a)*340,r:6,life:1.55,damage:280,team:'bot',color:'#ff6e79',owner});owner.ammo--;owner.reload=.72}
 else {for(let i=-1;i<=1;i++){const a=base+i*spread;shots.push({x:owner.x+Math.cos(a)*26,y:owner.y+Math.sin(a)*26,vx:Math.cos(a)*520,vy:Math.sin(a)*520,r:6,life:.82,damage:superShot?560:420,team:'player',color:superShot?'#ffe765':'#fff0a0',owner})}owner.ammo--;owner.reload=.55}
 owner.aimX=Math.cos(base);owner.aimY=Math.sin(base);pop(owner.x+Math.cos(base)*24,owner.y+Math.sin(base)*24,bot?'#ff8b89':'#fff2a1',3);
}
function shoot(){if(state!=='playing'||player.attackCd>0||player.ammo<=0)return;const t={x:pointer.x,y:pointer.y};if(Math.hypot(t.x-player.x,t.y-player.y)<10){t.x=player.x+player.aimX*100;t.y=player.y+player.aimY*100}fire(player,t);player.attackCd=.25;updateHud()}
function useSuper(){if(state!=='playing'||player.super<100)return;player.super=0;player.hp=Math.min(player.maxHp,player.hp+650);player.invuln=.8;const targets=bots.filter(b=>b.hp>0&&dist(player,b)<190);for(const b of targets){b.hp-=1450;pop(b.x,b.y,'#ffe45f',15);if(b.hp<=0)killBot(b)}for(let i=0;i<8;i++){let a=i*Math.PI/4;shots.push({x:player.x,y:player.y,vx:Math.cos(a)*440,vy:Math.sin(a)*440,r:9,life:.52,damage:800,team:'player',color:'#ffe45f',owner:player})}shake=.3;pop(player.x,player.y,'#fff291',28);say('SUPER BLAST!');updateHud()}
function killBot(b){if(b.hp<=0&&b.respawn<=0){b.respawn=3.2;pop(b.x,b.y,b.color,18);for(let i=0;i<2+Math.min(b.gems,2);i++)spawnGem(b.x+rand(-20,20),b.y+rand(-20,20));b.gems=0}}
function update(dt){elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}
 if(state!=='playing')return;
 matchTime-=dt;if(matchTime<=0){matchTime=0;finish(player.gems>=10)}
 let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x,my=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+joy.y;let ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml}move(player,mx*player.speed*dt,my*player.speed*dt);
 const dx=pointer.x-player.x,dy=pointer.y-player.y;if(Math.hypot(dx,dy)>8){player.aimX=dx/Math.hypot(dx,dy);player.aimY=dy/Math.hypot(dx,dy)}
 player.invuln=Math.max(0,player.invuln-dt);player.attackCd=Math.max(0,player.attackCd-dt);
 if(player.ammo<3){player.reload-=dt;if(player.reload<=0){player.ammo++;player.reload=player.ammo<3?.56:0;updateHud()}}
 if(pointer.down||keys.Space||touchAttack)shoot();
 // rival brawlers hunt and fire
 for(const b of bots){if(b.hp<=0){b.respawn-=dt;if(b.respawn<=0){b.hp=b.maxHp;b.x=rand(110,890);b.y=rand(110,590);b.attackCd=1;pop(b.x,b.y,b.color,12)}continue}
 b.attackCd-=dt;b.reload=Math.max(0,b.reload-dt);let tx=player.x-b.x,ty=player.y-b.y,d=Math.hypot(tx,ty)||1;b.aimX=tx/d;b.aimY=ty/d;
 let toward=d>270?1:d<155?-.72:0;let strafe=Math.sin(elapsed*1.5+b.x)*.5;move(b,(tx/d*toward-ty/d*strafe)*b.speed*dt,(ty/d*toward+tx/d*strafe)*b.speed*dt);
 if(d<520&&b.attackCd<=0&&b.ammo>0){fire(b,player,true);b.attackCd=rand(.65,1.05);if(b.ammo<=0)b.reload=1.3}
 if(b.ammo<=0&&b.reload<=0)b.ammo=3;
 }
 // projectiles
 for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.life<=0||blocked(s.x,s.y,s.r)){pop(s.x,s.y,s.color,2);shots.splice(i,1);continue}
 if(s.team==='bot'){if(player.invuln<=0&&dist(s,player)<s.r+player.r){player.hp-=s.damage;player.invuln=.16;player.super=Math.min(100,player.super+5);pop(player.x,player.y,'#ff7782',8);shake=.12;shots.splice(i,1);if(player.hp<=0)finish(false);updateHud()}}
 else {let hit=false;for(const b of bots){if(b.hp>0&&dist(s,b)<s.r+b.r){b.hp-=s.damage;player.super=Math.min(100,player.super+7);pop(s.x,s.y,'#ffe264',5);if(b.hp<=0)killBot(b);shots.splice(i,1);hit=true;updateHud();break}}if(hit)continue}
 }
 // gems appear from the central mine
 if(Math.floor(elapsed/4.5)!==Math.floor((elapsed-dt)/4.5)&&gems.length<11)spawnGem(500+rand(-43,43),350+rand(-38,38));
 for(let i=gems.length-1;i>=0;i--){let g=gems[i];g.bob+=dt*4;g.life-=dt;if(g.life<=0){gems.splice(i,1);continue}if(dist(g,player)<player.r+g.r+4){gems.splice(i,1);player.gems++;player.hp=Math.min(player.maxHp,player.hp+120);pop(g.x,g.y,'#48ffe3',12);say(player.gems>=10?'10 GEMS! GET OUT!':'+1 GEM');updateHud();if(player.gems>=10)finish(true)}}
